CREATE TABLE IF NOT EXISTS "panda_realty"."event_timelines" (
  "event_timeline_id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "property_list_id" bigint REFERENCES "panda_realty"."panda_properties" ("property_list_id") ON DELETE CASCADE,
  "event_order" numeric(10,1),
  "description" citext,
  "days" integer DEFAULT 0,
  "is_checked" boolean NOT NULL DEFAULT false,
  "recorded_at" timestamp,
  "notes" text,
  "event_timeline_amount" numeric(20,2),
  "is_row_to_be_printed" boolean NOT NULL DEFAULT false,
  "created_at" timestamp DEFAULT now(),
  "updated_at" timestamp
);
